import{_ as t,o,c as a,ag as n}from"./chunks/framework.B_zcDAFh.js";const g=JSON.parse('{"title":"Boing Bones","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-bones.md","filePath":"guide/boing-bones.md"}'),i={name:"guide/boing-bones.md"};function r(s,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="boing-bones" tabindex="-1">Boing Bones <a class="header-anchor" href="#boing-bones" aria-label="Permalink to &quot;Boing Bones&quot;">​</a></h1><p><strong>Boing Bones</strong> applies bouncy spring motion down a chain (or tree) of bones or plain transforms. Use it for hair, tails, antennae, jiggly props, jellyfish tentacles — anything where motion should propagate from a root outward.</p><h2 id="setting-up-a-chain" tabindex="-1">Setting Up a Chain <a class="header-anchor" href="#setting-up-a-chain" aria-label="Permalink to &quot;Setting Up a Chain&quot;">​</a></h2><ol><li>Add <code>BoingBones</code> to a GameObject.</li><li>In <strong>Bone Chains</strong>, set the <strong>Root</strong> transform. The bounce starts there and propagates through every descendant.</li><li>Optionally add more chains; each has its own root, exclusion list, and tuning.</li></ol><p>Each chain can opt out of effector reaction, override params, and exclude specific transforms from being included as bones.</p><h2 id="stiffness-and-shape" tabindex="-1">Stiffness and Shape <a class="header-anchor" href="#stiffness-and-shape" aria-label="Permalink to &quot;Stiffness and Shape&quot;">​</a></h2><p>Per-chain animation curves control how each property varies along the chain (root → tip):</p><ul><li><strong>Length Stiffness</strong> — resistance to stretching/compressing distance between bones.</li><li><strong>Pose Stiffness</strong> — resistance to deviating from the authored rest pose.</li><li><strong>Bend Angle Cap</strong> — maximum bend angle at each bone.</li><li><strong>Squash &amp; Stretch</strong> — how strongly bones squash/stretch with motion (<code>Max Squash</code>, <code>Max Stretch</code>).</li><li><strong>Animation Blend</strong> — blends between the raw (animated) pose and the boing-driven pose.</li><li><strong>Gravity</strong> — per-chain gravity vector.</li></ul><h2 id="collision" tabindex="-1">Collision <a class="header-anchor" href="#collision" aria-label="Permalink to &quot;Collision&quot;">​</a></h2><p>Boing Bones reacts to two kinds of colliders:</p><ul><li><strong>Boing Colliders</strong> — lightweight colliders provided by the kit (<code>BoingBoneCollider</code>). Cheaper than Unity physics; preferred for in-chain collision.</li><li><strong>Unity Colliders</strong> — standard <code>Collider</code> components, for collision against existing physics geometry.</li></ul><p>A per-chain <strong>Collision Radius</strong> curve controls the bone capsule thickness along the chain. Inter-chain collision can also be enabled.</p><h2 id="effector-reactivity" tabindex="-1">Effector Reactivity <a class="header-anchor" href="#effector-reactivity" aria-label="Permalink to &quot;Effector Reactivity&quot;">​</a></h2><p>Boing Bones reacts to <a href="./boing-effector.html">Boing Effectors</a> just like reactors do — wind, explosions, and player proximity disturb the chain naturally.</p><h2 id="twist-propagation" tabindex="-1">Twist Propagation <a class="header-anchor" href="#twist-propagation" aria-label="Permalink to &quot;Twist Propagation&quot;">​</a></h2><p>When enabled, axial twist propagates from parent to child using swing-twist decomposition (avoids rotational drift). On by default for new components; off on older ones for backward compatibility.</p><h2 id="avoiding-sudden-jumps-after-teleports" tabindex="-1">Avoiding Sudden Jumps After Teleports <a class="header-anchor" href="#avoiding-sudden-jumps-after-teleports" aria-label="Permalink to &quot;Avoiding Sudden Jumps After Teleports&quot;">​</a></h2><p>After teleporting a rig, call <code>BoingBones.HandleTeleport()</code> to reset chain state and avoid a high-velocity snap on the next update.</p><h2 id="update-order-with-other-procedural-animation" tabindex="-1">Update Order with Other Procedural Animation <a class="header-anchor" href="#update-order-with-other-procedural-animation" aria-label="Permalink to &quot;Update Order with Other Procedural Animation&quot;">​</a></h2><p>Boing Bones runs in <code>LateUpdate</code>. Other procedural-animation assets (IK, secondary motion) usually run there too, and Unity does not guarantee an order. Boing Kit must run <strong>last</strong> — set this in <strong>Edit &gt; Project Settings &gt; Script Execution Order</strong>. See the <a href="./faq.html">FAQ</a>.</p><h2 id="single-in-editor-camera-caveat" tabindex="-1">Single In-Editor Camera Caveat <a class="header-anchor" href="#single-in-editor-camera-caveat" aria-label="Permalink to &quot;Single In-Editor Camera Caveat&quot;">​</a></h2><p>Due to technical limitations, the effects of the BoingBones component can be displayed properly in only one editor tab. For example, if the scene view tab and the game view tab are both visible, then only one of them will display the effects properly. This only affects the Unity editor and does not affect in-game cameras if there are multiple ones. If there are cameras other than the main camera that render to off-screen render targets, then the effects should be rendered properly.</p><p>See the <a href="/boing-kit/api/boing-bones.html">API reference</a>.</p>',23)])])}const f=t(i,[["render",r]]);export{g as __pageData,f as default};
